mapper.select:
SELECT
    (
        SELECT COUNT(*)
        FROM orders
        INNER JOIN sales_sessions ON sales_sessions.id = orders.sales_session_id
        INNER JOIN dining_tables ON dining_tables.id = sales_sessions.table_id
        WHERE dining_tables.store_id = #{storeId}
          AND orders.created_at >= #{todayStart}
          AND orders.created_at < #{tomorrowStart}
    ) AS ordersToday,
    (
        SELECT COUNT(*)
        FROM sales_sessions
        INNER JOIN dining_tables ON dining_tables.id = sales_sessions.table_id
        WHERE dining_tables.store_id = #{storeId}
          AND sales_sessions.status = 'OPEN'
    ) AS activeTableCount,
    (
        SELECT COUNT(*)
        FROM dining_tables
        WHERE dining_tables.store_id = #{storeId}
    ) AS totalTableCount,
    (
        SELECT COUNT(*)
        FROM payments
        INNER JOIN sales_sessions ON sales_sessions.id = payments.sales_session_id
        INNER JOIN dining_tables ON dining_tables.id = sales_sessions.table_id
        WHERE dining_tables.store_id = #{storeId}
          AND payments.status = 'PENDING'
          AND NOT EXISTS (
              SELECT 1
              FROM unpaid_records
              WHERE unpaid_records.sales_session_id = payments.sales_session_id
          )
    ) AS pendingPaymentCount
